def __call__(self, s1: Sequence[T], s2: Sequence[T], prefix_weight: float = 0.1) -> float:
    s2, s1 = self._get_sequences(s1, s2)

    result = self.quick_answer(s1, s2)
    if result is not None:
        return result

    s1_len = len(s1)
    s2_len = len(s2)

    if not s1_len and not s2_len:
        return 0.0

    min_len = min(s1_len, s2_len)
    search_range = max(s1_len, s2_len)
    search_range = (search_range // 2)
    if search_range < 0:
        search_range = 0

    s1_flags = [False] * s1_len
    s2_flags = [False] * s2_len

    common_chars = 0
    for i, s1_ch in enumerate(s1):
        low = max(0, i - search_range)
        hi = min(i + search_range, s2_len - 1)
        for j in range(low, hi + 1):
            if not s2_flags[j] and s2[j] == s1_ch:
                s1_flags[i] = s2_flags[j] = True
                common_chars += 1

    if common_chars == 0:
        return 1.0

    k = trans_count = 0
    for i, s1_f in enumerate(s1_flags):
        if s1_f:
            for j in range(k, s2_len):
                if s2_flags[j]:
                    k = j
                    break
            if s1[i] != s2[j]:
                trans_count += 1
    trans_count = trans_count / 2

    weight = (common_chars / (s1_len + s2_len)) + (common_chars - trans_count) / common_chars
    weight /= 3

    if not self.winklerize:
        return weight
    if weight <= 0.8:
        return weight

    j = min(min_len, 4)
    i = 0
    while i < j and s1[i] != s2[i]:
        i += 1
    if i:
        weight += (i - 1) * prefix_weight * (1.0 - weight)

    if not self.long_tolerance or min_len <= 5:
        return weight
    if(common_chars <= i + 2 or 2 * common_chars < min_len + i):
        return weight
    tmp = (common_chars + i - 2) / (s1_len + s2_len - i * 3)
    return weight + (1.0 - weight) * tmp
